    const state = { writes: 0, postScan: 0, connected: null, lockHeld: true,
      messages: [], midiCalls: 0, otaPrompts: 0 };
    const ui = Object.fromEntries(["go", "stockgo", "stockconfirm", "conn", "bar"]
