/* SPDX-License-Identifier: GPL-3.0-only */
/* X0X motion lanes (firmware/src/seq/motion.c): record a sweep, play it back, ramp between steps,
 * a gap filled, a single touch, the knob winning while it moves and for a pass, a pattern
 * change, stop, and a reused slot. */
#include <stdio.h>
#include <string.h>
#include "../../firmware/src/seq/motion.h"

static int fails;
#define CHECK(c, ...) do { if (!(c)) { printf("  FAIL %s:%d: ", __FILE__, __LINE__); printf(__VA_ARGS__); printf("\n"); fails++; } } while (0)

static lane_t L[NLANE];
static motion_t M;
static int knob = 64, eng = 64, applies;   /* one parameter: the knob (base) and the engine's value */

static int base(void *x, int t, int v, int i) { (void)x; (void)t; (void)v; (void)i; return knob; }
static void apply(void *x, int t, int v, int i, int val) { (void)x; (void)t; (void)v; (void)i; eng = val; applies++; }

/* one pass of a 16-step part, `per` samples a step; with f, the knob is turned to f(step) before
 * each step, recording (lane k) */
static void pass(int pat, int per, int (*f)(int), int k)
{
    int s;
    for (s = 0; s < 16; s++) {
        if (f) {
            eng = knob = f(s);                         /* the knob turned: the engine has it at once */
            motion_req_rec(&M, k);
        }
        motion_tick(&M, (uint32_t)per / 2u);
        motion_step(&M, 0, pat, s, (s + 1) % 16, 16);
        motion_tick(&M, (uint32_t)per / 2u);
    }
}
static int sweep(int s) { return s * 8; }

/* A queued knob event must not survive transport stop/project-lane replacement.
 * A new post-stop event is still allowed to record or override the lane. */
static void test_stop_cancels_pending_knob_events(void)
{
    static lane_t lanes[NLANE];
    motion_t m;
    int k;
    memset(lanes, 0, sizeof lanes);
    motion_init(&m, lanes);
    m.base = base;
    m.apply = apply;
    k = motion_alloc(lanes, 0, 0, 2, 0, 0);
    CHECK(k >= 0, "stop cancellation lane allocated");
    if (k < 0)
        return;

    /* Recording event arrives, transport stops before that step fires, then restarts.
     * The previously programmed 37 must not be overwritten with the live knob 88. */
    lanes[k].val[1] = 37;
    eng = knob = 88;
    motion_req_rec(&m, k);
    motion_release(&m);
    motion_step(&m, 0, 0, 1, 2, 16);
    CHECK(lanes[k].val[1] == 37, "stopped record request changed saved lock (%u)", lanes[k].val[1]);
    CHECK(eng == 37, "stopped record request suppressed first playback (%d)", eng);

    /* A pending nonrecording override must not suppress the next pass. */
    motion_release(&m);
    lanes[k].val[2] = 46;
    eng = knob = 99;
    motion_req_hold(&m, k);
    motion_release(&m);
    motion_step(&m, 0, 0, 2, 3, 16);
    CHECK(eng == 46, "stopped hold request suppressed next pass (%d)", eng);

    /* Controls: a genuine event raised after release still works. */
    motion_release(&m);
    eng = knob = 79;
    motion_req_rec(&m, k);
    motion_step(&m, 0, 0, 3, 4, 16);
    CHECK(lanes[k].val[3] == 79, "fresh post-stop record discarded (%u)", lanes[k].val[3]);
    motion_release(&m);
    lanes[k].val[4] = 25;
    eng = knob = 82;
    motion_req_hold(&m, k);
    motion_step(&m, 0, 0, 4, 5, 16);
    CHECK(eng == 82, "fresh post-stop hold failed (%d)", eng);
    motion_release(&m);
    motion_step(&m, 0, 0, 4, 5, 16);
    CHECK(eng == 25, "released hold did not restore lane (%d)", eng);
}

int main(void)
{
    int k, k2, v;
    memset(L, 0, sizeof L);
    motion_init(&M, L);
    M.base = base;
    M.apply = apply;

    k = motion_alloc(L, 0, 0, 2, 0, 0);
    CHECK(k >= 0 && motion_count(L) == 1, "allocated");
    pass(0, 1000, 0, k);                               /* an empty lane plays the knob */
    CHECK(eng == 64, "an empty lane leaves the knob's value (%d)", eng);

    pass(0, 1000, sweep, k);                           /* record: a sweep over one pass */
    for (v = 0; v < 16; v++)
        CHECK(L[k].val[v] == v * 8, "recorded step %d = %d", v, L[k].val[v]);
    for (v = 0; v < MOT_GAP; v++)                      /* the gesture lasts MOT_GAP steps: the knob */
        motion_step(&M, 0, 0, v, v + 1, 16);
    CHECK(eng == 120, "just after the gesture the knob is heard (%d)", eng);

    knob = 5;                                          /* let go of the knob elsewhere */
    motion_tick(&M, 500);
    motion_step(&M, 0, 0, 0, 1, 16);
    CHECK(eng == 0, "playback: step 1 plays 0, not the knob (%d)", eng);
    motion_tick(&M, 500);
    CHECK(eng == 4, "ramp: halfway to step 2's 8 (%d)", eng);
    motion_tick(&M, 500);
    motion_step(&M, 0, 0, 1, 2, 16);
    CHECK(eng == 8, "step 2 (%d)", eng);

    L[k].val[2] = MOT_NONE;                            /* a step without a value: the knob */
    motion_step(&M, 0, 0, 2, 3, 16);
    CHECK(eng == 5, "a step with no value plays the knob (%d)", eng);

    motion_req_hold(&M, k);                            /* the knob wins for a pass */
    eng = knob = 99;
    for (v = 3; v < 16; v++) {
        motion_step(&M, 0, 0, v, (v + 1) % 16, 16);
        CHECK(eng == 99, "held: step %d plays the knob (%d)", v, eng);
    }
    for (v = 0; v < 3; v++)
        motion_step(&M, 0, 0, v, v + 1, 16);
    CHECK(eng == 99, "held: the knob's value through the pass (%d)", eng);
    motion_step(&M, 0, 0, 3, 4, 16);
    CHECK(eng == 24, "after the pass the lane again (%d)", eng);

    motion_step(&M, 0, 1, 4, 5, 16);                   /* the part changed pattern */
    CHECK(eng == 99, "another pattern: the knob (%d)", eng);
    motion_step(&M, 0, 0, 5, 6, 16);
    CHECK(eng == 40, "back on the pattern: the lane (%d)", eng);
    motion_step(&M, 1, 0, 6, 7, 16);
    CHECK(eng == 40, "another part's step does not touch it (%d)", eng);

    motion_release(&M);                                /* stop */
    CHECK(eng == 99 && motion_value(&M, k) < 0, "stop: the knob (%d)", eng);

    motion_step(&M, 0, 0, 6, 7, 16);
    CHECK(eng == 48, "playing again (%d)", eng);
    motion_clear(&M, k);                                /* cleared while applying; the slot reused */
    CHECK(eng == knob, "clear restores the knob base (%d, knob %d)", eng, knob);
    k2 = motion_alloc(L, 0, 0, 2, 0, 1);
    CHECK(k2 == k, "the slot is reused");
    L[k2].val[7] = 48;                                 /* the stale runtime applied 48: must still apply */
    applies = 0;
    motion_step(&M, 0, 0, 7, 8, 16);
    CHECK(applies == 1 && eng == 48, "a reused slot starts fresh (applies %d)", applies);

    /* a gap: touches on steps 2 and 5 fill 3 and 4; a lone touch writes one step */
    k2 = motion_alloc(L, 2, 0, 2, 0, 2);
    eng = knob = 30;
    motion_req_rec(&M, k2);
    motion_step(&M, 0, 2, 2, 3, 16);
    motion_step(&M, 0, 2, 3, 4, 16);
    motion_step(&M, 0, 2, 4, 5, 16);
    eng = knob = 60;
    motion_req_rec(&M, k2);
    motion_step(&M, 0, 2, 5, 6, 16);
    CHECK(L[k2].val[2] == 30 && L[k2].val[3] == 40 && L[k2].val[4] == 50 && L[k2].val[5] == 60,
          "gap filled: %d %d %d %d", L[k2].val[2], L[k2].val[3], L[k2].val[4], L[k2].val[5]);
    for (v = 6; v < 6 + MOT_GAP + 2; v++)
        motion_step(&M, 0, 2, v, v + 1, 16);
    eng = knob = 90;
    motion_req_rec(&M, k2);
    motion_step(&M, 0, 2, 13, 14, 16);                 /* a new gesture: no line back to step 5 */
    CHECK(L[k2].val[12] == MOT_NONE && L[k2].val[13] == 90 && L[k2].val[6] == MOT_NONE,
          "a lone touch writes its step only (%d %d %d)", L[k2].val[12], L[k2].val[13], L[k2].val[6]);

    for (v = 0; v < NLANE; v++)                        /* the pool fills, and says so */
        if (motion_alloc(L, 3, 1, 0, v & 7, v >> 3) < 0)
            break;
    CHECK(v == NLANE - 2 && motion_alloc(L, 3, 1, 1, 0, 0) == -1, "pool of %d: full after %d more", NLANE, v);
    CHECK(motion_find(L, 3, 1, 0, 2, 1) >= 0 && motion_find(L, 4, 1, 0, 2, 1) < 0, "find keys on the pattern");
    test_stop_cancels_pending_knob_events();
    printf("motion: %s\n", fails ? "FAIL" : "ok");
    return fails != 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Host proof: Chicago GateRev insert adds gated-reverb colour vs dry native303. */
#include <math.h>
#include <stdio.h>
#include <string.h>
#include "bass303.h"
#include "chicago_gaterev.h"
#include "chicago_fx.h"

static int fails;
#define CHECK(c, ...)                                                                                                  \
    do {                                                                                                               \
        if (!(c)) {                                                                                                    \
            printf("FAIL " __VA_ARGS__);                                                                               \
            printf("\n");                                                                                              \
            fails++;                                                                                                   \
        }                                                                                                              \
    } while (0)

static float buf[8192];
static float dry[8192];

static void render_note(bass303_t *b, float *out, int n)
{
    int pos = 0;
    bass303_init(b);
    bass303_set(b, BASS303_CUTOFF, 100);
    bass303_set(b, BASS303_RESO, 40);
    bass303_set(b, BASS303_ENVMOD, 0);
    bass303_set(b, BASS303_WAVE, 0);
    bass303_set(b, BASS303_GNAW, 0);
    bass303_set(b, BASS303_BITE, 0);
    bass303_set(b, BASS303_VOLUME, 100);
    bass303_set(b, BASS303_DRIVE, 0);
    bass303_set(b, BASS303_AMPMODE, BASS303_AMP_GATE);
    bass303_note_on_velocity(b, 48, 0, 0, 100);
    while (pos < n) {
        int m = n - pos > 128 ? 128 : n - pos;
        bass303_render(b, out + pos, m);
        pos += m;
    }
}

static double rms_delta(const float *a, const float *b, int n)
{
    double s = 0;
    int i;
    for (i = 0; i < n; i++) {
        double d = (double)a[i] - (double)b[i];
        s += d * d;
    }
    return sqrt(s / (double)n);
}

static void test_supported_flags(void)
{
    CHECK(chi_fx_supported(CHI_FX_GATE_REV), "GateRev supported");
    CHECK(chi_fx_is_insert(CHI_FX_GATE_REV), "GateRev is insert");
    CHECK(chi_fx_is_gaterev_insert(CHI_FX_GATE_REV), "GateRev gaterev-insert helper");
    CHECK(!chi_fx_is_not_yet(CHI_FX_GATE_REV), "GateRev not NOT_YET");
    CHECK(strstr(CHI_FX_TYPE_N[CHI_FX_GATE_REV], "—") == 0, "GateRev label has no em-dash");
}

static void test_map_clears_sends(void)
{
    chicago_fx_out_t o;
    chicago_fx_map(CHI_FX_GATE_REV, 28, 31, 0, &o);
    CHECK(o.touch == CHI_FX_W_CLEAR_SENDS, "GateRev insert clears sends");
    CHECK(!(o.touch & CHI_FX_W_MX_REV), "GateRev does not set Mix reverb");
    CHECK(!(o.touch & CHI_FX_W_RV_DEC), "GateRev does not set RvDec");
    CHECK(!(o.touch & CHI_FX_W_RV_LVL), "GateRev does not set RvLvl");
}

static void test_gaterev_changes_pcm(void)
{
    bass303_t b;
    chi_gaterev_t grev;
    int n = 4096, skip = 512;
    double delta, delta_hi;
    render_note(&b, dry, n);

    memcpy(buf, dry, (size_t)n * sizeof(float));
    chi_gaterev_init(&grev);
    chi_gaterev_set(&grev, 28, 31, BASS303_SR); /* Summer Bass-ish */
    chi_gaterev_process(&grev, buf + skip, n - skip);
    delta = rms_delta(dry + skip, buf + skip, n - skip);
    CHECK(delta > 1e-4, "GateRev changes waveform (rms delta %g)", delta);

    memcpy(buf, dry, (size_t)n * sizeof(float));
    chi_gaterev_init(&grev);
    chi_gaterev_set(&grev, 127, 127, BASS303_SR);
    chi_gaterev_process(&grev, buf + skip, n - skip);
    delta_hi = rms_delta(dry + skip, buf + skip, n - skip);
    CHECK(delta_hi > delta * 1.02, "higher wet/decay moves PCM more (lo %g hi %g)", delta, delta_hi);

    memcpy(buf, dry, (size_t)n * sizeof(float));
    chi_gaterev_init(&grev);
    chi_gaterev_process(&grev, buf + skip, n - skip);
    CHECK(memcmp(buf + skip, dry + skip, (size_t)(n - skip) * sizeof(float)) == 0,
          "unset GateRev leaves PCM unchanged");
}

int main(void)
{
    test_supported_flags();
    test_map_clears_sends();
    test_gaterev_changes_pcm();
    if (fails) {
        printf("%d FAIL(s)\n", fails);
        return 1;
    }
    printf("PASS chicago_gaterev\n");
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Regression for MID-15: one MIDI clock origin at a time. The first source
 * holds a clock lease for 0.4 s, and a new USB/BLE source may not advance
 * the sequencer while the old source still owns its clock. */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "sequencer.h"

static unsigned checks, failures, test_id, block_size;
#define CHECK(cond) do { ++checks; if (!(cond)) { ++failures; if (failures < 30u) \
    fprintf(stderr, "FAIL scenario=%u block=%u line=%u: %s\n", test_id, block_size, (unsigned)__LINE__, #cond); } } while (0)

typedef struct {
    unsigned steps, on, off, duplicate, orphan, clock_echo, transport_echo, breaks;
    unsigned held;
    unsigned last_step;
    uint8_t open[16][128];
} monitor_t;
static pattern_t pats[NPAT];
static void out_midi(void *opaque, uint8_t status, uint8_t note, uint8_t velocity)
{
    monitor_t *m=(monitor_t *)opaque;
    unsigned hi=status&0xf0u, ch=status&0x0fu;
    if (status>=0xf8u) { if(status==0xf8u)m->clock_echo++; else m->transport_echo++; return; }
    if (hi==0x90u && velocity) {
        m->on++;
        if(m->open[ch][note])m->duplicate++;
        else {m->open[ch][note]=1; m->held++;}
    } else if(hi==0x80u || (hi==0x90u && !velocity)) {
        m->off++;
        if(!m->open[ch][note])m->orphan++;
        else {m->open[ch][note]=0; m->held--;}
    }
}
static void on_step(void *opaque,int part,int index)
{
    monitor_t *m=(monitor_t *)opaque;
    if(part==TRK_BASS0) { m->steps++; m->last_step=(unsigned)index; }
}
static void on_break(void *opaque){ ((monitor_t *)opaque)->breaks++; }
static int on_drum(void *opaque,int p,int k,float vel){(void)opaque;(void)p;(void)k;(void)vel;return 1;}
static int on_bass(void *opaque,int p,int n,int a,int slide,int velocity){(void)opaque;(void)p;(void)n;(void)a;(void)slide;(void)velocity; return 1; }
static void off_bass(void *opaque,int p){(void)opaque;(void)p;}
static void render(seq_t *s,const seq_sink_t *sink,uint32_t frames)
{
    while(frames) {
        uint32_t packet=frames<block_size?frames:block_size;
        frames-=packet;
        while(packet) {
            uint32_t step=seq_until_event(s,packet);
            CHECK(step>0u && step<=packet);
            if(!step || step>packet)return;
            seq_advance(s,step,sink);
            packet-=step;
        }
    }
}
static int recv(seq_t *s,uint8_t status,uint32_t input)
{
    if(!seq_clk_take(s,status,input))return 0;
    CHECK(seq_midi_rt(s,status)==1);
    return 1;
}
static void init(seq_t *s,monitor_t *m,seq_sink_t *sink)
{
    unsigned p,k;
    memset(pats,0,sizeof pats);
    for(p=0;p<NPAT;p++)pattern_init(&pats[p],p+17u,p+39u);
    for(k=0;k<16u;k++)pats[0].bass[0].step[k]=(bstep_t){(uint8_t)(60+k%3),G_NOTE|BS_SLIDE,110};
    pats[0].bass[0].len=16u;
    seq_init(s,pats);
    s->clk_src=SEQ_CLK_EXT;
    s->send_clock=1;
    s->send_notes=1;
    memset(m,0,sizeof *m);
    memset(sink,0,sizeof *sink);
    sink->ctx=m;
    sink->midi=out_midi;
    sink->step=on_step;
    sink->brk_stop=on_break;
    sink->drum=on_drum;
    sink->bass_on=on_bass;
    sink->bass_off=off_bass;
    render(s,sink,1u);
}
static void start_usb(seq_t *s,monitor_t *m,const seq_sink_t *sink)
{
    CHECK(recv(s,0xfau,0u));
    CHECK(recv(s,0xf8u,0u));
    render(s,sink,1u);
    CHECK(s->playing && s->ext);
    CHECK(s->clk_lock==1u && m->steps==1u && m->last_step==0u);
    CHECK(m->held==1u && m->on==1u && m->off==0u);
}
static void timeout_takeover(void)
{
    seq_t s;monitor_t m;seq_sink_t sink;
    init(&s,&m,&sink);start_usb(&s,&m,&sink);
    /* First owner USB renewed the lock at frame 1. A competing BLE F8 and
       Start at t < 0.4 s must be rejected, not counted as extra PPQN. */
    CHECK(!recv(&s,0xf8u,1u));
    CHECK(!recv(&s,0xfau,1u));
    CHECK(s.clk_lock==1u && s.ext_pending==0u);
    render(&s,&sink,SEQ_LOCK_T-1u);
    CHECK(!recv(&s,0xf8u,1u));
    CHECK(!recv(&s,0xfau,1u));
    CHECK(s.clk_lock==1u && m.steps==1u);
    /* The next audio frame expires the lease before the next MIDI packet. */
    render(&s,&sink,1u);
    CHECK(recv(&s,0xf8u,1u)); /* a new link owns the next available tick */
    CHECK(s.clk_lock==2u);
    CHECK(s.ext_skip==1u && s.ext_pending==1u);
    render(&s,&sink,1u);
    CHECK(m.steps==1u && m.held==1u && m.off==0u);
    CHECK(!recv(&s,0xf8u,0u)); /* stale USB clock is rejected */
    CHECK(s.ext_pending==0u && m.steps==1u);
    for(unsigned tick=1;tick<=4u;tick++) {
        CHECK(recv(&s,0xf8u,1u));
        render(&s,&sink,1u);
        CHECK(m.steps==1u);
    }
    CHECK(recv(&s,0xf8u,1u));
    render(&s,&sink,1u);
    CHECK(m.steps==2u && m.last_step==1u);
    CHECK(!recv(&s,0xfcu,0u)); /* USB Stop must not affect BLE playback */
    render(&s,&sink,1u);
    CHECK(s.playing && m.steps==2u);
    CHECK(recv(&s,0xfcu,1u));
    render(&s,&sink,1u);
    CHECK(!s.playing && m.held==0u && m.on==m.off);
    CHECK(m.orphan==0u && m.duplicate==0u);
    CHECK(m.breaks==1u);
    CHECK(m.clock_echo==0u && m.transport_echo==0u);
}
static void stopped_lease(void)
{
    seq_t s;monitor_t m;seq_sink_t sink;
    init(&s,&m,&sink);start_usb(&s,&m,&sink);
    CHECK(recv(&s,0xfcu,0u));
    render(&s,&sink,1u);
    CHECK(!s.playing && m.on==m.off && m.held==0u);
    CHECK(s.clk_stop && s.clk_lock==1u);
    CHECK(!recv(&s,0xfau,1u));
    render(&s,&sink,SEQ_LOCK_T+1u);
    CHECK(recv(&s,0xfau,1u));
    CHECK(s.clk_lock==2u);
    CHECK(recv(&s,0xf8u,1u));
    render(&s,&sink,1u);
    CHECK(s.playing && m.steps==2u && m.last_step==0u);
    CHECK(m.on==2u && m.off==1u && m.held==1u);
    CHECK(!recv(&s,0xfcu,0u));
    CHECK(recv(&s,0xfcu,1u));
    render(&s,&sink,1u);
    CHECK(!s.playing && m.on==m.off && m.held==0u);
    CHECK(!m.orphan && !m.duplicate);
    CHECK(!m.clock_echo && !m.transport_echo);
}
int main(void)
{
    const unsigned blocks[]={1u,64u,1024u};
    for(unsigned i=0;i<3u;i++){
        block_size=blocks[i]; test_id=1u; timeout_takeover(); test_id=2u; stopped_lease();
    }
    fprintf(stderr,"seq clock owner handoff: %u/%u checks %s\n",checks-failures,checks,failures?"FAILED":"PASSED");
    return failures?EXIT_FAILURE:EXIT_SUCCESS;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Included by ble.c after the two role services. TIMER5 is the sole owner of
 * the host union and the mailbox consumer. Never restart the RF/core-1 image. */
static uint8_t ble_role_changing;
static uint32_t ble_role_at;

static void ble_service(void)
{
    uint8_t next = (uint8_t)(smc_ble_role_get() != 0);
    uint8_t addr[6];
    unsigned i;
    int stopped;
    if (ble_up && next != ble_central_role && !ble_role_changing) {
        ble_role_changing = 1;
        ble_role_at = fm1_ms;
    }
    if (ble_central_role) ble_central_service();
    else ble_device_service();
    if (!ble_up) return;
    if (next == ble_central_role) { ble_role_changing = 0; return; }
    if (ble_central_role)
        stopped = blec_pair_stopped(&ble_r.host.c, &ble_r.host.c2);
    else
        stopped = !ble_link_st && !ble_r.host.h.cmd_wait &&
                  (ble_r.host.h.state == BLEH_IDLE ||
                   (ble_r.host.h.state == BLEH_ADVERTISING && !ble_r.host.h.want_adv));
    if (!stopped || xb_ring_used(&ble_r.mb.c2h) || xb_ring_used(&ble_r.mb.h2c)) {
        /* A controller that never acknowledges stop is not safe to reuse. */
        if (fm1_ms - ble_role_at >= 3000u) ble_fail();
        return;
    }
    for (i = 0; i < sizeof addr; i++)
        addr[i] = ble_central_role ? ble_r.host.c.addr[i] : ble_r.host.h.addr[i];
    ble_central_link_notify(0);
    smk_apc_ble_link(0, 0);
    ble_r.orr = ble_r.ow;
    ble_sx_n = ble_sx_over = ble_sx_reply = ble_sx_ch = 0;
    if (next) {
        blec_init(&ble_r.host.c, ble_send, ble_central_midi, 0, addr);
        blec_init(&ble_r.host.c2, ble_send, ble_central_midi, (void *)1, addr);
        blec_pair_bind(&ble_r.host.c, &ble_r.host.c2);
    } else {
        blec_pair_bind(0, 0);
        bleh_init(&ble_r.host.h, ble_send, 0, ble_r.nm, addr);
        bleh_set_sysex(&ble_r.host.h, ble_sysex_in);
    }
    ble_host_on = 0;  /* next tick starts the new role with its HCI Reset */
    ble_central_role = next;
    ble_role_changing = 0;
}

